package main

import (
	"errors"
	"fmt"
)

var ErrNoName = errors.New("no name on the roster")

// signIn is fixed. It writes the sentry into the gate book.
func signIn(name string) error {
	if name == "" {
		return ErrNoName
	}
	fmt.Println(name, "on duty")
	return nil
}

// signOut is fixed. It closes the sentry's entry in the gate book.
func signOut(name string) {
	fmt.Println(name, "off duty")
}

func patrol(name string, posts []string) error {
	if err := signIn(name); err != nil {
		return err
	}
	defer signOut(name)
	for i, post := range posts {
		if post == "breach" {
			return fmt.Errorf("breach at post %d", i+1)
		}
		fmt.Println("checking", post)
	}
	return nil
}

