import "fmt"

// Depot is fixed. It is a dead-end shed. Floats reverse in one at a time, so
// the float nearest the door is the only one that can leave.
type Depot struct {
	inside []string
}

// enter is fixed. It parks name at the door end of the shed.
func (d *Depot) enter(name string) {
	d.inside = append(d.inside, name)
	fmt.Println(name, "enters")
}

// leave is fixed. Only the float at the door can leave.
func (d *Depot) leave(name string) {
	last := len(d.inside) - 1
	if last < 0 || d.inside[last] != name {
		fmt.Println(name, "is blocked in")
		return
	}
	fmt.Println(name, "leaves")
	d.inside = d.inside[:last]
}

