question.answer:
package main

import "fmt"

// Order is fixed. It is one instruction from the trading floor.
type Order struct {
	Symbol string
	Qty    int
}

// price is fixed. It belongs to a matching engine nobody on the floor can
// edit. It charges the book price per share plus each share's part of a 12
// fee, rounded down by integer division, and it panics on a symbol missing
// from the book.
func price(book map[string]int, o Order) int {
	p, ok := book[o.Symbol]
	if !ok {
		panic("unknown symbol " + o.Symbol)
	}
	perShare := p + 12/o.Qty
	return perShare * o.Qty
}

func fill(book map[string]int, o Order) (cost int, err error) {
	defer settle(o.Symbol, &err)
	return price(book, o), nil
}

func settle(symbol string, err *error) {
	if r := recover(); r != nil {
		*err = fmt.Errorf("fill %s: %v", symbol, r)
	}
}

func session(book map[string]int, orders []Order) []string {
	var lines []string
	for _, o := range orders {
		cost, err := fill(book, o)
		if err != nil {
			lines = append(lines, err.Error())
			continue
		}
		lines = append(lines, fmt.Sprintf("%s x%d = %d", o.Symbol, o.Qty, cost))
	}
	return lines
}

func quote(book map[string]int, o Order) (int, error) {
	p, ok := book[o.Symbol]
	if !ok {
		return 0, fmt.Errorf("unknown symbol %s", o.Symbol)
	}
	if o.Qty == 0 {
		return 0, fmt.Errorf("zero quantity for %s", o.Symbol)
	}
	perShare := p + 12/o.Qty
	return perShare * o.Qty, nil
}

testcode.text:
book := map[string]int{"AAPL": 150, "MSFT": 400}
cost, err := fill(book, Order{Symbol: "ZZZ", Qty: 5})
fmt.Println(cost, err)

book := map[string]int{"AAPL": 150, "MSFT": 400}
orders := []Order{{Symbol: "AAPL", Qty: 2}, {Symbol: "MSFT", Qty: 3}}
for _, line := range session(book, orders) {
	fmt.Println(line)
}

var e error
settle("AAPL", &e)
fmt.Println(e == nil)
func() {
	defer func() { fmt.Println(e) }()
	defer settle("BOOM", &e)
	panic("engine down")
}()
book := map[string]int{"AAPL": 150, "MSFT": 400}
orders := []Order{{Symbol: "AAPL", Qty: 4}, {Symbol: "ZZZ", Qty: 1}, {Symbol: "MSFT", Qty: 0}, {Symbol: "MSFT", Qty: 1}}
for _, line := range session(book, orders) {
	fmt.Println(line)
}
cost, err := quote(book, Order{Symbol: "MSFT", Qty: 0})
fmt.Println(cost, err)
cost, err = quote(book, Order{Symbol: "ZZZ", Qty: 1})
fmt.Println(cost, err)
cost, err = quote(book, Order{Symbol: "AAPL", Qty: 4})
fmt.Println(cost, err == nil)
